(627845, 64362, 12252, '<td valign="top">My top pick for the challenge. Simply lovely.</td>', 'My top pick for the challenge. Simply lovely.', '2004-03-18 18:52:41.000000', NULL, 1),
(627846, 64678, 12252, '<td valign="top">Adorable, meets the challenge, even the cow''s expressions are "parallel," so it''s one of my top picks. 8</td>', 'Adorable, meets the challenge, even the cow''s expressions are "parallel," so it''s one of my top picks. 8', '2004-03-18 18:53:56.000000', NULL, 1),
(627851, 64683, 12252, '<td valign="top">Pretty phenomenal shot. Great colors. Has that "Miami Vice" sort of look to it I gave it an 8</td>', 'Pretty phenomenal shot. Great colors. Has that "Miami Vice" sort of look to it I gave it an 8', '2004-03-18 18:55:02.000000', NULL, 1),
(627854, 64740, 12252, '<td valign="top">Wonderful light, composition, focus and DOF. My only nit would be to get the person in the background out of the shot. 8</td>', 'Wonderful light, composition, focus and DOF. My only nit would be to get the person in the background out of the shot. 8', '2004-03-18 18:57:32.000000', NULL, 1),
(627855, 64487, 245, '<td valign="top">I''m a little disconcerted by the out of focus foreground in the this one, I do like the composition though... just wish more were in focus! :)</td>', 'I''m a little disconcerted by the out of focus foreground in the this one, I do like the composition though... just wish more were in focus! :)', '2004-03-18 18:58:31.000000', NULL, 1),
(627856, 64774, 12252, '<td valign="top">Took me a moment to figure out the subject, but that was good! Meets the challenge perfectly. Would have liked to see a frame of some sort. The lettering on the third piece of wood (from the left) on the top is distracting, but outside your control. 8</td>', 'Took me a moment to figure out the subject, but that was good! Meets the challenge perfectly. Would have liked to see a frame of some sort. The lettering on the third piece of wood (from the left) on the top is distracting, but outside your control. 8', '2004-03-18 18:59:01.000000', NULL, 1),
(627859, 64933, 12252, '<td valign="top">Beautifully done, light an dairy, and well composed with the triangles of parallel lines tilted as they are. Should be a top competitor in this challenge. 8</td>', 'Beautifully done, light an dairy, and well composed with the triangles of parallel lines tilted as they are. Should be a top competitor in this challenge. 8', '2004-03-18 19:00:12.000000', NULL, 1),
(627889, 64855, 10339, '<td valign="top">Nice use of shadows and hoghlights. I like the cropping.</td>', 'Nice use of shadows and hoghlights. I like the cropping.', '2004-03-18 19:39:48.000000', NULL, 1),
(627892, 64678, 10339, '<td valign="top">Really neat shot! Great use of the space.</td>', 'Really neat shot! Great use of the space.', '2004-03-18 19:40:56.000000', NULL, 1),
