(629244, 64461, 14476, '<td valign="top">An imaginative way to interpret the Challenge.  Good luck!</td>', 'An imaginative way to interpret the Challenge.  Good luck!', '2004-03-19 22:46:24.000000', NULL, 1),
(629245, 65002, 14476, '<td valign="top">Lovely colors and good composition.  Oh yes, those power lines.  Good idea:  if you can''t lose them, include them in the title!  8</td>', 'Lovely colors and good composition.  Oh yes, those power lines.  Good idea:  if you can''t lose them, include them in the title!  8', '2004-03-19 22:47:16.000000', NULL, 1),
(629246, 64769, 14476, '<td valign="top">Good one.  Like the non-conformity of the bent one asit gives the composition added interest. Could be in slightly better focus.  Still, an excellent take on the Challenge.</td>', 'Good one.  Like the non-conformity of the bent one asit gives the composition added interest. Could be in slightly better focus.  Still, an excellent take on the Challenge.', '2004-03-19 22:51:26.000000', NULL, 1),
