(629399, 64740, 12510, '<td valign="top">Fyndið ég held að þetta sé sami göngustígurinn og ég ætlað að nota sem myndefni!</td>', 'Fyndið ég held að þetta sé sami göngustígurinn og ég ætlað að nota sem myndefni!', '2004-03-20 07:47:46.000000', NULL, 1),
(629419, 64700, 9073, '<td valign="top">very nice. 9</td>', 'very nice. 9', '2004-03-20 08:26:20.000000', NULL, 1),
