(631247, 64611, 11467, '<td valign="top">And Beyond!!! ??<br/>I like the picture.</td>', 'And Beyond!!! ??I like the picture.', '2004-03-22 08:17:56.000000', NULL, 1),
(631250, 64766, 11467, '<td valign="top">Maybe the background is too much in focus, and distracts from the actual image of the guitar</td>', 'Maybe the background is too much in focus, and distracts from the actual image of the guitar', '2004-03-22 08:19:31.000000', NULL, 1),
(631253, 64691, 11467, '<td valign="top">I''m impressed, if not of the photograph, then of the patirnce in creating this..<br/>The photo is actually pretty good.</td>', 'I''m impressed, if not of the photograph, then of the patirnce in creating this..The photo is actually pretty good.', '2004-03-22 08:21:39.000000', NULL, 1),
