(632467, 64621, 18318, '<td valign="top">my studio.... who broke in....</td>', 'my studio.... who broke in....', '2004-03-22 20:00:34.000000', NULL, 1),
(632528, 64362, 14614, '<td valign="top">oooo - if only I could see the veins on the tip of the leaf... great as presented -- one of my picks for a ribbon</td>', 'oooo - if only I could see the veins on the tip of the leaf... great as presented -- one of my picks for a ribbon', '2004-03-22 21:27:30.000000', NULL, 1),
(632529, 65005, 14614, '<td valign="top">inventive take on the theme - one of my favorites</td>', 'inventive take on the theme - one of my favorites', '2004-03-22 21:28:09.000000', NULL, 1),
(632537, 65024, 6179, '<td valign="top">very nice contrast and nice sense of depth. One of my favorites.</td>', 'very nice contrast and nice sense of depth. One of my favorites.', '2004-03-22 21:46:29.000000', NULL, 1),
(632538, 64740, 6179, '<td valign="top">I love this photo. Nice.</td>', 'I love this photo. Nice.', '2004-03-22 21:47:37.000000', NULL, 1),
(632539, 64507, 6179, '<td valign="top">Looks very menacing.</td>', 'Looks very menacing.', '2004-03-22 21:48:32.000000', NULL, 1),
(632540, 64749, 6179, '<td valign="top">Nice lines</td>', 'Nice lines', '2004-03-22 21:48:48.000000', NULL, 1),
(632541, 64188, 6179, '<td valign="top">I love the way you captured the sky. Very nice however not entirely parallel.</td>', 'I love the way you captured the sky. Very nice however not entirely parallel.', '2004-03-22 21:50:12.000000', NULL, 1),
(632542, 64316, 6179, '<td valign="top">I only count 1,678.987</td>', 'I only count 1,678.987', '2004-03-22 21:51:08.000000', NULL, 1),
(632544, 64710, 14773, '<td valign="top">nice idea, nice lines, but not very interesting</td>', 'nice idea, nice lines, but not very interesting', '2004-03-22 21:52:03.000000', NULL, 1),
(632545, 65010, 6179, '<td valign="top">Not really parallel lines but would have worked well for curved lines.</td>', 'Not really parallel lines but would have worked well for curved lines.', '2004-03-22 21:52:15.000000', NULL, 1),
(632547, 64553, 6179, '<td valign="top">Nice focus. Like the shallow DOF to emphasize the parallel text. Would have scored higher from me if parallel would have been spelled correctly.</td>', 'Nice focus. Like the shallow DOF to emphasize the parallel text. Would have scored higher from me if parallel would have been spelled correctly.', '2004-03-22 21:53:59.000000', NULL, 1),
(632549, 64747, 6179, '<td valign="top">IMO the lighting was a bit too harsh. Some softer light would have gotten you more points from me.</td>', 'IMO the lighting was a bit too harsh. Some softer light would have gotten you more points from me.', '2004-03-22 21:55:52.000000', NULL, 1),
(632550, 65025, 6179, '<td valign="top">Nice angle. A bit sharper focus maybe?</td>', 'Nice angle. A bit sharper focus maybe?', '2004-03-22 21:56:31.000000', NULL, 1),
(632554, 64909, 6179, '<td valign="top">Looks like when you resized this that you did not keep the aspect ratio the same and squashed the photo a little. Nice perspective though.</td>', 'Looks like when you resized this that you did not keep the aspect ratio the same and squashed the photo a little. Nice perspective though.', '2004-03-22 21:57:35.000000', NULL, 1),
(632555, 64666, 6179, '<td valign="top">nicely done.</td>', 'nicely done.', '2004-03-22 21:57:56.000000', NULL, 1),
(632559, 64780, 6179, '<td valign="top">I love the reflection in the water. Nice.</td>', 'I love the reflection in the water. Nice.', '2004-03-22 21:59:45.000000', NULL, 1),
