INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(632561, 64725, 6179, '<td valign="top">unique perspective. I like it.</td>', 'unique perspective. I like it.', '2004-03-22 22:00:55.000000', NULL, 1),
(632564, 64686, 6179, '<td valign="top">I like your use of black and white and low angle perspective.</td>', 'I like your use of black and white and low angle perspective.', '2004-03-22 22:02:32.000000', NULL, 1),
(632565, 64363, 3724, '<td valign="top">Superior title!  The moss growing on the fence is interesting and unusuall.  Strange camera angle here.  The centered vertical orientation of the barbed wire is not ordinary compared to the usuall horizontal  view.  I enjoy looking at the fence this way, and makes me wonder if this picture has been turned on end.  Tight little border is a nice subtle addition to the image.</td>', 'Superior title!  The moss growing on the fence is interesting and unusuall.  Strange camera angle here.  The centered vertical orientation of the barbed wire is not ordinary compared to the usuall horizontal  view.  I enjoy looking at the fence this way, and makes me wonder if this picture has been turned on end.  Tight little border is a nice subtle addition to the image.', '2004-03-22 22:02:52.000000', NULL, 1),
(632566, 65019, 6179, '<td valign="top">Nice focus and DOF.</td>', 'Nice focus and DOF.', '2004-03-22 22:03:28.000000', NULL, 1),
(632567, 64987, 6179, '<td valign="top">does not really meet the challenge. No parallel lines here.</td>', 'does not really meet the challenge. No parallel lines here.', '2004-03-22 22:04:55.000000', NULL, 1),
(632568, 64691, 6179, '<td valign="top">I''ll bet that took a while. Nice DOF and focus.</td>', 'I''ll bet that took a while. Nice DOF and focus.', '2004-03-22 22:06:26.000000', NULL, 1),
(632573, 64758, 17937, '<td valign="top">Awesome!  So much motion and yet nice still parallel linesl...</td>', 'Awesome!  So much motion and yet nice still parallel linesl...', '2004-03-22 22:14:04.000000', NULL, 1),
(632650, 64869, 18802, '<td valign="top">Very dramatic use of empty space and constrast. I like this.</td>', 'Very dramatic use of empty space and constrast. I like this.', '2004-03-22 23:20:27.000000', NULL, 1),
(632662, 64395, 16106, '<td valign="top">Georgous shot. some people will rip you because these lines are not parallel enough but this is the first shot I have seen where the lines help or reinforce the subject rather than ARE the subject. Bet it will print nicely too. 10</td>', 'Georgous shot. some people will rip you because these lines are not parallel enough but this is the first shot I have seen where the lines help or reinforce the subject rather than ARE the subject. Bet it will print nicely too. 10', '2004-03-22 23:26:13.000000', NULL, 1),
(632676, 64678, 18802, '<td valign="top">I enjoy the composition. Pleasing to the eye.</td>', 'I enjoy the composition. Pleasing to the eye.', '2004-03-22 23:35:03.000000', NULL, 1),
(632689, 64988, 18802, '<td valign="top">Well done.</td>', 'Well done.', '2004-03-22 23:41:04.000000', NULL, 1),
(632692, 64587, 18802, '<td valign="top">Grainy.</td>', 'Grainy.', '2004-03-22 23:42:02.000000', NULL, 1),
(632695, 64829, 18802, '<td valign="top">Under exposed.</td>', 'Under exposed.', '2004-03-22 23:43:21.000000', NULL, 1),
