(632700, 64983, 18802, '<td valign="top">Plenty of intensity. I like this.</td>', 'Plenty of intensity. I like this.', '2004-03-22 23:46:44.000000', NULL, 1),
(632703, 65008, 18802, '<td valign="top">?</td>', '?', '2004-03-22 23:50:11.000000', NULL, 1),
(632708, 64322, 18802, '<td valign="top">Skyshot with bulb setting?</td>', 'Skyshot with bulb setting?', '2004-03-22 23:53:14.000000', NULL, 1),
(632709, 64267, 18802, '<td valign="top">Doesn''t do it for me.</td>', 'Doesn''t do it for me.', '2004-03-22 23:54:16.000000', NULL, 1),
(632711, 64455, 18802, '<td valign="top">Creative.</td>', 'Creative.', '2004-03-22 23:55:13.000000', NULL, 1),
(632716, 64578, 18802, '<td valign="top">I don''t normally go for this kind of shot but the top of the lamp is interesting against the sky and pole. Good shot in keeping with the challenge.</td>', 'I don''t normally go for this kind of shot but the top of the lamp is interesting against the sky and pole. Good shot in keeping with the challenge.', '2004-03-22 23:56:50.000000', NULL, 1),
(632721, 64613, 18802, '<td valign="top">Too busy for my taste.</td>', 'Too busy for my taste.', '2004-03-22 23:58:23.000000', NULL, 1),
(632725, 64456, 18802, '<td valign="top">I like the background. Fern maybe a bit soft or more resolution needed?</td>', 'I like the background. Fern maybe a bit soft or more resolution needed?', '2004-03-23 00:00:46.000000', NULL, 1),
(632727, 64909, 18802, '<td valign="top">Barrel distortion?</td>', 'Barrel distortion?', '2004-03-23 00:01:51.000000', NULL, 1),
(632731, 64722, 18802, '<td valign="top">Makes me feel like I''m in a big room. Pictures that make me feel are pictures I like.</td>', 'Makes me feel like I''m in a big room. Pictures that make me feel are pictures I like.', '2004-03-23 00:03:42.000000', NULL, 1),
(632734, 64395, 18802, '<td valign="top">Can''t say I''ve ever seen snow do that before. Nice shot and nice contrast with the roof shakers.</td>', 'Can''t say I''ve ever seen snow do that before. Nice shot and nice contrast with the roof shakers.', '2004-03-23 00:05:32.000000', NULL, 1),
